import { Button, ToastProvider, useToast } from '@larose-ui/react';

function Demo() {
  const { toast } = useToast();
  return (
    <Button
      variant="primary"
      onClick={() =>
        toast({ title: 'Saved', message: 'Your changes were stored.', variant: 'success' })
      }
    >
      Show toast
    </Button>
  );
}

export default function App() {
  return (
    <ToastProvider placement="bottom-right">
      <Demo />
    </ToastProvider>
  );
}
